    flow: '이 단원은 쪽지에 적은 생각을 묶는 일에서 시작해 재료와 용구를 거쳐 조형 원리로 이어지는 29차시이다. 1~10차시에서는 흩어진 쪽지를 묶어 이름을 붙이고, 두 묶음을 이어 넓힌 주제를 한 문장으로 쓰며, 밑그림 두 가지를 만들어 고른 까닭을 설명하고 쓰지 않은 쪽지를 되살려 계획을 고친다. 11~20차시에서는 손 그림과 디지털 그림의 장단점을 표로 견주고, 주제의 느낌에 맞는 재료를 근거로 고르며, 층·저장·가위·한지·자료의 출처와 뒷정리 같은 용구 쓰임을 익힌 뒤 고른 재료가 뜻을 나타냈는지 판단하고 다음 재료 목록을 만든다. 21~28차시에서는 크기와 색의 균형과 서로 맞서는 균형, 어울림이 만드는 느낌, 강조를 익혀 화면을 짜고 쓴 원리가 주제를 살렸는지 판단해 어울리지 않는 곳을 한 군데씩 고친다. 29차시에서는 단원의 세 갈래를 묶고 작품 한 점을 완성하며 스스로 평가한다.',
